+                if candidate_span < existing_span {
+                    // The newcomer is more specific; it survives instead.
+                    merged.push((existing.id.clone(), candidate.id.clone()));
+                    *existing = candidate;
+                } else {
+                    merged.push((candidate.id.clone(), existing.id.clone()));
+                }
+            }
+        }
+    }
+
+    (kept, merged)
