+            k.issue_type == candidate.issue_type
+                && k.location.overlaps(&candidate.location, tolerance)
+        });
+
+        match duplicate_of {
+            None => kept.push(candidate),
+            Some(existing) => {
+                let existing_span = existing.location.end_line - existing.location.start_line;
