317 |     );
318 | 
319 |     let value = match extract_json(&resp.text) {
320 |         Ok(v) => v,
321 |         Err(e) => {
322 |             traj.push(TrajectoryEvent::Note {
323 |                 note: format!("unparseable review response: {e}"),
324 |             });
325 |             return Vec::new();
326 |         }
327 |     };
