329 |     let parsed = parse_review(&value, &format!("{}-adv", case.id()));
330 |     for w in &parsed.warnings {
331 |         traj.push(TrajectoryEvent::Note { note: w.clone() });
332 |     }
333 |     for c in &parsed.candidates {
334 |         traj.push(TrajectoryEvent::CandidateProposed {
335 |             candidate: c.clone(),
336 |         });
337 |     }
338 |     parsed.candidates
