 50 | /// `id_prefix` disambiguates ids across stages within a case.
 51 | pub fn parse_review(value: &serde_json::Value, id_prefix: &str) -> ParsedReview {
 52 |     let mut candidates = Vec::new();
 53 |     let mut warnings = Vec::new();
 54 | 
 55 |     let Some(items) = value.get("findings").and_then(|f| f.as_array()) else {
 56 |         warnings.push("response had no `findings` array".to_string());
 57 |         return ParsedReview {
 58 |             candidates,
 59 |             warnings,
 60 |         };
 61 |     };
 62 | 
 63 |     for (i, item) in items.iter().enumerate() {
 64 |         let raw: RawFinding = match serde_json::from_value(item.clone()) {
 65 |             Ok(r) => r,
 66 |             Err(e) => {
 67 |                 warnings.push(format!("finding[{i}] dropped: {e}"));
 68 |                 continue;
 69 |             }
 70 |         };
 71 | 
 72 |         let Some(issue_type) = parse_issue_type(&raw.issue_type) else {
 73 |             warnings.push(format!(
 74 |                 "finding[{i}] dropped: issue_type {:?} is not in the controlled taxonomy",
 75 |                 raw.issue_type
 76 |             ));
 77 |             continue;
 78 |         };
 79 | 
 80 |         if raw.start_line == 0 {
 81 |             warnings.push(format!(
 82 |                 "finding[{i}] dropped: start_line 0 (lines are 1-based)"
 83 |             ));
 84 |             continue;
 85 |         }
 86 | 
 87 |         if raw.claim.trim().is_empty() {
 88 |             warnings.push(format!("finding[{i}] dropped: empty claim"));
 89 |             continue;
 90 |         }
 91 | 
 92 |         let end_line = raw.end_line.unwrap_or(raw.start_line).max(raw.start_line);
 93 | 
 94 |         candidates.push(CandidateFinding {
 95 |             id: format!("{id_prefix}-{}", i + 1),
 96 |             issue_type,
 97 |             severity: parse_severity(raw.severity.as_deref()),
 98 |             location: Location::new(&raw.file, raw.start_line, end_line),
 99 |             claim: raw.claim.trim().to_string(),
100 |             reasoning: raw.reasoning.trim().to_string(),
101 |         });
102 |     }
103 | 
104 |     ParsedReview {
105 |         candidates,
106 |         warnings,
107 |     }
108 | }
