110 | /// Repository-relative paths touched by a unified diff.
111 | pub fn changed_files(diff: &str) -> Vec<String> {
112 |     let mut files = Vec::new();
113 |     for line in diff.lines() {
114 |         // Prefer the "+++ b/path" side: it names the file's post-change path.
115 |         if let Some(rest) = line.strip_prefix("+++ ") {
116 |             let path = rest.trim();
117 |             if path == "/dev/null" {
118 |                 continue;
119 |             }
120 |             let path = path
121 |                 .strip_prefix("b/")
122 |                 .or_else(|| path.strip_prefix("a/"))
123 |                 .unwrap_or(path);
124 |             // Strip a trailing timestamp column, which some diff tools add.
125 |             let path = path.split('\t').next().unwrap_or(path).trim();
126 |             let normalized = crate::finding::normalize_path(path);
127 |             if !normalized.is_empty() && !files.contains(&normalized) {
128 |                 files.push(normalized);
129 |             }
130 |         }

