 80 | impl Location {
 81 |     pub fn new(file: impl Into<String>, start_line: u32, end_line: u32) -> Self {
 82 |         let (start_line, end_line) = if start_line <= end_line {
 83 |             (start_line, end_line)
 84 |         } else {
 85 |             (end_line, start_line)
 86 |         };
 87 |         Self {
 88 |             file: normalize_path(&file.into()),
 89 |             start_line,
 90 |             end_line,
 91 |         }
 92 |     }
 93 | 
 94 |     /// True when the two line ranges overlap once `tolerance` lines of slack
 95 |     /// are added to each end of `self`. Files must match exactly.
 96 |     pub fn overlaps(&self, other: &Location, tolerance: u32) -> bool {
 97 |         if self.file != other.file {
 98 |             return false;
 99 |         }
100 |         let lo = self.start_line.saturating_sub(tolerance);
101 |         let hi = self.end_line.saturating_add(tolerance);
102 |         lo <= other.end_line && other.start_line <= hi
103 |     }
104 | }
